//! The Auto Profile fit's C-FFI return codes for the WinUI host (#5458).
use raw_core::view::auto_profile::AutoFitOutcome;

pub fn emit_cs() -> String {
    format!(
        "// Generated by codegen --schema auto-fit-codes. Do not edit.\n\nnamespace Maple.WinUI.Generated;\n\n/// <summary>Auto Profile fit return codes from raw-ffi, single-sourced from\n/// raw-core's <c>AutoFitOutcome</c> (#5458).</summary>\npublic static class AutoFitCodes\n{{\n    /// <summary>Auto was selected but no embedded camera preview could be\n    /// extracted; out-params match rc 1 and the host renders Neutral.</summary>\n    public const int NoPreview = {};\n}}\n",
        AutoFitOutcome::NO_PREVIEW_FFI_CODE
    )
}
